{
  "findings": [
    {
      "check_id": "CKV_AZURE_88",
      "title": "Azure Function App uses plain text storage account access key",
      "resource": "azurerm_linux_function_app.alert_function",
      "severity": "CRITICAL",
      "explanation": "The storage_account_access_key is hardcoded in plain text, posing a significant security risk if the Terraform configuration is exposed or accessed by unauthorized parties."
    }
  ],
  "patched_code": "resource "azurerm_linux_function_app" "alert_function" {
  name                = "smart-manufacturing-iot-monitoring-platform-function-app-alerts"
  resource_group_name = azurerm_resource_group.smart_manufacturing.name
  location            = azurerm_resource_group.smart_manufacturing.location
  service_plan_id     = azurerm_service_plan.dashboard_plan.id
  storage_account_name       = azurerm_storage_account.function_storage.name
  storage_uses_managed_identity = true
  site_config {
    application_stack {
      node_version = "18"
    }
  }
  app_settings = {
    "FUNCTIONS_WORKER_RUNTIME" = "node"
  }
}",
  "fix_summary": "Replaced storage_account_access_key with storage_uses_managed_identity to use managed identity for authentication instead of plain text access key."
}
